/* ===========================================================================
   PMEX root.css - the ONE stylesheet of the site.
   1. Color variables: --c-HEX (and --brand-*). Every color of the site is defined here, nowhere else.
   2. Design tokens built only from those colors: gradients (--grad-*), shadows (--shadow-*),
      transitions (--transition-*) and the hover lift (--lift-hover).
   3. Color classes: .c-HEX (text), .bg-c-HEX (background), .bdr-c-HEX (border).
   4. All page styles, one block per former stylesheet / inline <style> block. Every rule in a block starts
      with [data-css~="name"]; a page lists the blocks it uses in <html data-css="...">. The blocks are in the
      same order the pages used to load them, so the cascade is unchanged.
   Rule: write colors only as var(--c-HEX) below section 1. No color literal, no extra stylesheet.
   =========================================================================== */

@layer pmex-inline, pmex-green-cta, pmex-buttons, reference-typography, properties, theme, base, components, utilities;

/* Brand names (AGENTS.md palette) */
:root{
  --brand-primary:#3F9A4B;
  --brand-dark:#2E4A25;
  --brand-light:#AAD39C;
  --brand-tint:#F8FBF0;
  --brand-text:#505050;
  --brand-border:#E0E0DA;
  --brand-white:#FFFFFF;
  --brand-orange:#E85D3F;
}
.c-brand-primary{color:var(--brand-primary)}.bg-c-brand-primary{background-color:var(--brand-primary)}.bdr-c-brand-primary{border-color:var(--brand-primary)}
.c-brand-dark{color:var(--brand-dark)}.bg-c-brand-dark{background-color:var(--brand-dark)}.bdr-c-brand-dark{border-color:var(--brand-dark)}
.c-brand-light{color:var(--brand-light)}.bg-c-brand-light{background-color:var(--brand-light)}.bdr-c-brand-light{border-color:var(--brand-light)}
.c-brand-tint{color:var(--brand-tint)}.bg-c-brand-tint{background-color:var(--brand-tint)}.bdr-c-brand-tint{border-color:var(--brand-tint)}
.c-brand-text{color:var(--brand-text)}.bg-c-brand-text{background-color:var(--brand-text)}.bdr-c-brand-text{border-color:var(--brand-text)}
.c-brand-border{color:var(--brand-border)}.bg-c-brand-border{background-color:var(--brand-border)}.bdr-c-brand-border{border-color:var(--brand-border)}
.c-brand-white{color:var(--brand-white)}.bg-c-brand-white{background-color:var(--brand-white)}.bdr-c-brand-white{border-color:var(--brand-white)}
.c-brand-orange{color:var(--brand-orange)}.bg-c-brand-orange{background-color:var(--brand-orange)}.bdr-c-brand-orange{border-color:var(--brand-orange)}

