/* ===== inline <style> block  [data-css~="inline-c2f56f36"] ===== */
@layer pmex-green-cta;

/* ===== css/site-buttons.css  [data-css~="site-buttons"] ===== */
/* Single source of truth for website CTA and form buttons.
   Keep this stylesheet before the other stylesheets so its important layer wins. */
@layer pmex-buttons {
 :root[data-css~="site-buttons"] {
  --pmex-button-background:var(--c-AAD39C);
  --pmex-button-text:var(--c-2E4A25);
  --pmex-button-hover:var(--c-9FCB91);
  --pmex-button-font-size:14px;
  --pmex-button-radius:9999px;
 }
 [data-css~="site-buttons"] [data-site-button] {
  display:inline-flex!important;align-items:center!important;justify-content:center!important;
  gap:8px!important;box-sizing:border-box!important;
  font-family:Inter,sans-serif!important;font-size:var(--pmex-button-font-size)!important;
  font-weight:400!important;line-height:20px!important;letter-spacing:normal!important;text-transform:none!important;
  padding:10px 24px!important;min-height:40px!important;height:auto!important;
  border:0!important;border-radius:var(--pmex-button-radius)!important;
  background:var(--pmex-button-background)!important;background-image:none!important;
  color:var(--pmex-button-text)!important;box-shadow:none!important;text-decoration:none!important;
  white-space:normal!important;max-width:100%;cursor:pointer;
  transition:background-color .2s ease,box-shadow .2s ease!important;
 }
 [data-css~="site-buttons"] [data-site-button] :is(span,strong,b) {color:inherit!important;font:inherit!important;}
 [data-css~="site-buttons"] [data-site-button]:hover {background:var(--pmex-button-hover)!important;color:var(--pmex-button-text)!important;}
 [data-css~="site-buttons"] [data-site-button]:focus-visible {outline:2px solid var(--c-3F9A4B)!important;outline-offset:3px!important;}
 [data-css~="site-buttons"] [data-site-button]:disabled,[data-css~="site-buttons"] [data-site-button][aria-disabled="true"] {opacity:.55;cursor:not-allowed;}
 @media(prefers-reduced-motion:reduce) {[data-css~="site-buttons"] [data-site-button]{transition:none!important;}}
}

/* Hero CTA pair: assessment text link beside the filled demo pill. */
@layer pmex-buttons {
 [data-css~="site-buttons"] [data-site-button="link"], [data-css~="site-buttons"] [data-site-button="link"]:hover {
  background:transparent!important;background-image:none!important;color:var(--c-3F9A4B)!important;
  padding:0!important;min-height:40px!important;border:0!important;border-radius:0!important;box-shadow:none!important;
  font-size:16px!important;line-height:24px!important;font-weight:400!important;
 }
 [data-css~="site-buttons"] [data-site-button="link"][data-cta-arrow]::after {content:"\2192";margin-left:4px;}
 [data-css~="site-buttons"] [data-site-button="link"]:hover {text-decoration:underline!important;text-underline-offset:4px;}
}

/* Pricing unlock action matches the shared navbar demo gradient. */
@layer pmex-buttons {
 [data-css~="site-buttons"] .pricing-gate #pricing-form button[data-site-button="primary"] {
  background:var(--grad-pill)!important;
 }
 [data-css~="site-buttons"] .pricing-gate #pricing-form button[data-site-button="primary"]:is(:hover,:focus-visible) {
  background:var(--grad-a)!important;
 }
}

/* Opt-in pill that matches the shared navbar "Schedule a Demo" gradient (data-demo-gradient). */
@layer pmex-buttons {
 [data-css~="site-buttons"] [data-site-button="pill"][data-demo-gradient] {
  background:var(--grad-pill)!important;
  color:var(--c-2E4A25)!important;
 }
 [data-css~="site-buttons"] [data-site-button="pill"][data-demo-gradient]:is(:hover,:focus-visible) {
  background:var(--grad-a)!important;
  color:var(--c-2E4A25)!important;
 }
}
/* Dropdowns (every form select): the native arrow sits against the right border, so it is replaced by a drawn chevron
   placed 20-26px inside the edge, with room for the text before it. Only the arrow changes: fill, border and height stay
   with each form. The :is(#_, ...) wrappers only add id weight, so this outranks the forms' own !important padding and
   background shorthands (some of them sit under two ids). */
html[data-css~="site-buttons"]:is(#_,html) :is(#_,body) select:is(#_,select):not([multiple]):not([size]) {
  -webkit-appearance:none!important;
  appearance:none!important;
  padding-right:48px!important;
  cursor:pointer;
  background-image:linear-gradient(45deg,transparent 40%,var(--c-505050) 40%,var(--c-505050) 60%,transparent 60%),linear-gradient(135deg,transparent 40%,var(--c-505050) 40%,var(--c-505050) 60%,transparent 60%)!important;
  background-position:calc(100% - 27px) 50%,calc(100% - 20px) 50%!important;
  background-size:7px 7px,7px 7px!important;
  background-repeat:no-repeat!important;
}


