/* ===== css/site-faq-accordion.css  [data-css~="site-faq-accordion-2"] ===== */
/* Site-wide FAQ / accordion look matching index.html #pmex-faq
   Soft card, sage hover gradient, lift + shadow, circular chevron. */

:root[data-css~="site-faq-accordion-2"] {
  --pmex-faq-border: var(--c-DDE5DA);
  --pmex-faq-border-hover: var(--c-AAD39C);
  --pmex-faq-shadow: 0 18px 40px -12px var(--c-2A3828-a28);
  --pmex-faq-radius: 18px;
  --pmex-faq-icon-bg: var(--c-F5F7F3);
  --pmex-faq-icon-bg-open: var(--c-EEF5EB);
  --pmex-faq-green: var(--c-3F9A4B);
  --pmex-faq-text: var(--c-505050);
  --pmex-faq-body: var(--c-696E67);
  --pmex-faq-answer-bg: var(--c-F8FAF5);
  --pmex-faq-answer-border: var(--c-E8EEE5);
}

/* Shared card shell */
html[data-css~="site-faq-accordion-2"] body :is(.faq-item, .fi, .dm-acc, .mb-acc, [data-faq-item]) {
  position: relative !important;
  isolation: isolate;
  overflow: hidden !important;
  border-radius: var(--pmex-faq-radius) !important;
  border: 1px solid var(--pmex-faq-border) !important;
  background: var(--c-FFFFFF) !important;
  box-shadow: none !important;
  margin: 0 !important;
  transition:
    transform 0.3s ease,
    border-color 0.3s ease,
    box-shadow 0.3s ease,
    background-color 0.3s ease !important;
}

/* Index-style sage gradient wash on hover / open (skip if page already has .feature-card-gradient) */
html[data-css~="site-faq-accordion-2"] body :is(.faq-item, .fi, .dm-acc, .mb-acc, [data-faq-item]):not(:has(.feature-card-gradient))::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  background: var(--grad-w);
  opacity: 0;
  transition: var(--transition-fade);
}

html[data-css~="site-faq-accordion-2"] body :is(.faq-item, .fi, .dm-acc, .mb-acc, [data-faq-item]) > * {
  position: relative;
  z-index: 1;
}

@media (hover: hover) and (pointer: fine) {
  html[data-css~="site-faq-accordion-2"] body :is(.faq-item, .fi, .dm-acc, .mb-acc, [data-faq-item]):hover {
    transform: var(--lift-hover) !important;
    border-color: var(--pmex-faq-border-hover) !important;
    box-shadow: var(--pmex-faq-shadow) !important;
  }

  html[data-css~="site-faq-accordion-2"] body :is(.faq-item, .fi, .dm-acc, .mb-acc, [data-faq-item]):not(:has(.feature-card-gradient)):hover::before {
    opacity: 1;
  }
}

html[data-css~="site-faq-accordion-2"] body :is(.faq-item, .fi, .dm-acc, .mb-acc, [data-faq-item]):focus-within {
  border-color: var(--pmex-faq-border-hover) !important;
  box-shadow: var(--pmex-faq-shadow) !important;
}

html[data-css~="site-faq-accordion-2"] body :is(.faq-item, .fi, .dm-acc, .mb-acc, [data-faq-item]):not(:has(.feature-card-gradient)):focus-within::before {
  opacity: 1;
}

/* Open / expanded state keeps the soft elevated look */
html[data-css~="site-faq-accordion-2"] body :is(
  .faq-item.open,
  .faq-item:has([aria-expanded="true"]),
  .fi.open,
  .dm-acc.is-open,
  .mb-acc.is-open,
  [data-faq-item]:has([aria-expanded="true"])
) {
  border-color: var(--pmex-faq-border-hover) !important;
  box-shadow: var(--pmex-faq-shadow) !important;
}

html[data-css~="site-faq-accordion-2"] body :is(
  .faq-item.open,
  .faq-item:has([aria-expanded="true"]),
  .fi.open,
  .dm-acc.is-open,
  .mb-acc.is-open,
  [data-faq-item]:has([aria-expanded="true"])
):not(:has(.feature-card-gradient))::before {
  opacity: 1;
}

/* Stack / grid spacing + alignment (cards were touching after margin reset) */
html[data-css~="site-faq-accordion-2"] body :is(.space-y-2, .space-y-3, .dm-accs, .mb-accs, [data-faq-list]) {
  display: flex !important;
  flex-direction: column !important;
  gap: 12px !important;
}

html[data-css~="site-faq-accordion-2"] body .faq-cols {
  display: grid !important;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr) !important;
  gap: 12px 20px !important;
  align-items: start !important;
}

/* Each FAQ column stacks its questions with even vertical gaps */
html[data-css~="site-faq-accordion-2"] body .faq-cols > * {
  display: flex !important;
  flex-direction: column !important;
  gap: 12px !important;
  min-width: 0 !important;
  align-items: stretch !important;
}

/* Fallback when FAQ cards are direct siblings without a flex/gap parent */
html[data-css~="site-faq-accordion-2"] body :is(.faq-item, .fi, .dm-acc, .mb-acc, [data-faq-item]) + :is(.faq-item, .fi, .dm-acc, .mb-acc, [data-faq-item]) {
  margin-top: 12px !important;
}

html[data-css~="site-faq-accordion-2"] body .faq-cols :is(.fi, .faq-item) + :is(.fi, .faq-item),
html[data-css~="site-faq-accordion-2"] body :is(.space-y-2, .space-y-3, .dm-accs, .mb-accs, [data-faq-list]) > :is(.faq-item, .fi, .dm-acc, .mb-acc, [data-faq-item]) + :is(.faq-item, .fi, .dm-acc, .mb-acc, [data-faq-item]) {
  margin-top: 0 !important;
}

@media (max-width: 900px) {
  html[data-css~="site-faq-accordion-2"] body .faq-cols {
    grid-template-columns: minmax(0, 1fr) !important;
  }
}

/* Triggers */
html[data-css~="site-faq-accordion-2"] body :is(.faq-trigger, .fi-q, .dm-acc-t, .mb-acc-t, [data-faq-button]) {
  display: flex !important;
  width: 100% !important;
  align-items: center !important;
  justify-content: space-between !important;
  gap: 16px !important;
  padding: 16px 20px !important;
  text-align: left !important;
  background: transparent !important;
  border: 0 !important;
  box-shadow: none !important;
  cursor: pointer;
  color: var(--pmex-faq-text) !important;
  font-family: Inter, sans-serif !important;
  font-size: 14px !important;
  font-weight: 500 !important;
  line-height: 1.45 !important;
  min-height: 0 !important;
  height: auto !important;
  border-radius: 0 !important;
}

html[data-css~="site-faq-accordion-2"] body :is(.faq-trigger, .fi-q, .dm-acc-t, .mb-acc-t, [data-faq-button]):hover {
  background: transparent !important;
}

html[data-css~="site-faq-accordion-2"] body :is(.faq-trigger, .dm-acc-t, .mb-acc-t, [data-faq-button]) > span:first-child,
html[data-css~="site-faq-accordion-2"] body .fi-qt {
  color: var(--pmex-faq-text) !important;
  font-size: 14px !important;
  font-weight: 500 !important;
  line-height: 1.45 !important;
}

/* Circular chevron treatment */
html[data-css~="site-faq-accordion-2"] body .faq-icon,
html[data-css~="site-faq-accordion-2"] body .fi-ch,
html[data-css~="site-faq-accordion-2"] body [data-faq-icon] {
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  width: 28px !important;
  height: 28px !important;
  flex-shrink: 0 !important;
  border-radius: 9999px !important;
  background: var(--pmex-faq-icon-bg) !important;
  color: var(--pmex-faq-green) !important;
  transition: transform 0.3s ease, background-color 0.3s ease, color 0.3s ease !important;
}

html[data-css~="site-faq-accordion-2"] body .faq-trigger > svg.faq-icon,
html[data-css~="site-faq-accordion-2"] body .dm-acc-t > svg,
html[data-css~="site-faq-accordion-2"] body .mb-acc-t > svg {
  width: 28px !important;
  height: 28px !important;
  padding: 7px;
  box-sizing: border-box;
  border-radius: 9999px !important;
  background: var(--pmex-faq-icon-bg) !important;
  color: var(--pmex-faq-green) !important;
  transition: transform 0.3s ease, background-color 0.3s ease !important;
}

html[data-css~="site-faq-accordion-2"] body :is(.faq-item.open, .faq-item:has([aria-expanded="true"])) .faq-icon,
html[data-css~="site-faq-accordion-2"] body .fi.open .fi-ch,
html[data-css~="site-faq-accordion-2"] body :is(.dm-acc.is-open, .mb-acc.is-open) > :is(.dm-acc-t, .mb-acc-t) > svg,
html[data-css~="site-faq-accordion-2"] body [data-faq-item]:has([aria-expanded="true"]) [data-faq-icon] {
  background: var(--pmex-faq-icon-bg-open) !important;
  color: var(--pmex-faq-green) !important;
  transform: rotate(180deg) !important;
}

/* Specialty open icon used rotate(45deg) + white stroke — normalize to index chevron flip */
html[data-css~="site-faq-accordion-2"] body .fi.open .fi-ch {
  transform: rotate(180deg) !important;
  background: var(--pmex-faq-icon-bg-open) !important;
}

html[data-css~="site-faq-accordion-2"] body .fi.open .fi-ch svg :is(path, use) {
  stroke: var(--pmex-faq-green) !important;
}

html[data-css~="site-faq-accordion-2"] body .fi-ch svg path {
  stroke: var(--pmex-faq-green) !important;
}

/* Answer panels */
html[data-css~="site-faq-accordion-2"] body :is(.faq-content, .faq-panel, .fi-a, .dm-acc-b, .mb-acc-b, [data-faq-answer]) {
  color: var(--pmex-faq-body) !important;
  background: transparent !important;
}

html[data-css~="site-faq-accordion-2"] body :is(.faq-content, .faq-panel, .dm-acc-b, .mb-acc-b) {
  border-top: 1px solid var(--pmex-faq-answer-border);
  background: var(--pmex-faq-answer-bg) !important;
