}

html[data-css~="site-faq-accordion-2"] body :is(.faq-content, .faq-panel, .fi-a, .dm-acc-b, .mb-acc-b, [data-faq-answer]) p,
html[data-css~="site-faq-accordion-2"] body :is(.faq-content, .fi-a, .dm-acc-b, .mb-acc-b) {
