/* Nested answer wrappers inside index-style markup */
html[data-css~="site-faq-accordion-2"] body [data-faq-answer] .border-t,
html[data-css~="site-faq-accordion-2"] body [data-faq-answer] [class*="bg-[var(--c-F8FAF5)]"] {
