 }
 [data-css~="site-motion-2"] [data-site-motion-control] {
  transition:transform .25s ease,box-shadow .25s ease,background-color .25s ease,color .25s ease;
 }
 @media(hover:hover) and (pointer:fine) {
  [data-css~="site-motion-2"] [data-site-motion-card]:hover { box-shadow:var(--shadow-x); }
 }
 [data-css~="site-motion-2"] [data-site-motion-card]:focus-visible { box-shadow:var(--shadow-x); }
}
