/* Shared card shell */
html[data-css~="site-faq-accordion-3"] body :is(.faq-item, .fi, .dm-acc, .mb-acc, [data-faq-item]) {
  position: relative !important;
  isolation: isolate;
  overflow: hidden !important;
  border-radius: var(--pmex-faq-radius) !important;
  border: 1px solid var(--pmex-faq-border) !important;
  background: var(--c-FFFFFF) !important;
  box-shadow: none !important;
  margin: 0 !important;
  transition:
    transform 0.3s ease,
    border-color 0.3s ease,
    box-shadow 0.3s ease,
    background-color 0.3s ease !important;
}

/* Index-style sage gradient wash on hover / open (skip if page already has .feature-card-gradient) */
html[data-css~="site-faq-accordion-3"] body :is(.faq-item, .fi, .dm-acc, .mb-acc, [data-faq-item]):not(:has(.feature-card-gradient))::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  background: var(--grad-w);
  opacity: 0;
  transition: var(--transition-fade);
}

html[data-css~="site-faq-accordion-3"] body :is(.faq-item, .fi, .dm-acc, .mb-acc, [data-faq-item]) > * {
  position: relative;
  z-index: 1;
}

@media (hover: hover) and (pointer: fine) {
  html[data-css~="site-faq-accordion-3"] body :is(.faq-item, .fi, .dm-acc, .mb-acc, [data-faq-item]):hover {
    transform: var(--lift-hover) !important;
    border-color: var(--pmex-faq-border-hover) !important;
    box-shadow: var(--pmex-faq-shadow) !important;
  }

  html[data-css~="site-faq-accordion-3"] body :is(.faq-item, .fi, .dm-acc, .mb-acc, [data-faq-item]):not(:has(.feature-card-gradient)):hover::before {
    opacity: 1;
  }
}

html[data-css~="site-faq-accordion-3"] body :is(.faq-item, .fi, .dm-acc, .mb-acc, [data-faq-item]):focus-within {
  border-color: var(--pmex-faq-border-hover) !important;
  box-shadow: var(--pmex-faq-shadow) !important;
}

html[data-css~="site-faq-accordion-3"] body :is(.faq-item, .fi, .dm-acc, .mb-acc, [data-faq-item]):not(:has(.feature-card-gradient)):focus-within::before {
