/* ===== css/site-motion.css  [data-css~="site-motion-3"] ===== */
/* Keep hover geometry steady to avoid pointer-edge enter/leave oscillation.
   Existing card lifts remain; shared emphasis adds only a soft shadow. */
@media(prefers-reduced-motion:no-preference) {
 [data-css~="site-motion-3"] [data-site-motion-card] {
  transition:transform .3s cubic-bezier(.25,.1,.25,1),box-shadow .3s ease,border-color .3s ease,background-color .3s ease,color .3s ease;
 }
 [data-css~="site-motion-3"] [data-site-motion-control] {
  transition:transform .25s ease,box-shadow .25s ease,background-color .25s ease,color .25s ease;
 }
 @media(hover:hover) and (pointer:fine) {
  [data-css~="site-motion-3"] [data-site-motion-card]:hover { box-shadow:var(--shadow-x); }
 }
 [data-css~="site-motion-3"] [data-site-motion-card]:focus-visible { box-shadow:var(--shadow-x); }
}
/* Keep native <summary> steady; FAQ cards use index-style lift from site-faq-accordion.css */
[data-css~="site-motion-3"] summary,
[data-css~="site-motion-3"] summary:hover {
 translate:none !important;
 transform:none !important;
}

/* ===== css/site-faq-accordion.css  [data-css~="site-faq-accordion-4"] ===== */
/* Site-wide FAQ / accordion look matching index.html #pmex-faq
   Soft card, sage hover gradient, lift + shadow, circular chevron. */

:root[data-css~="site-faq-accordion-4"] {
  --pmex-faq-border: var(--c-DDE5DA);
  --pmex-faq-border-hover: var(--c-AAD39C);
  --pmex-faq-shadow: 0 18px 40px -12px var(--c-2A3828-a28);
  --pmex-faq-radius: 18px;
  --pmex-faq-icon-bg: var(--c-F5F7F3);
  --pmex-faq-icon-bg-open: var(--c-EEF5EB);
  --pmex-faq-green: var(--c-3F9A4B);
  --pmex-faq-text: var(--c-505050);
  --pmex-faq-body: var(--c-696E67);
  --pmex-faq-answer-bg: var(--c-F8FAF5);
  --pmex-faq-answer-border: var(--c-E8EEE5);
}

/* Shared card shell */
html[data-css~="site-faq-accordion-4"] body :is(.faq-item, .fi, .dm-acc, .mb-acc, [data-faq-item]) {
  position: relative !important;
  isolation: isolate;
  overflow: hidden !important;
  border-radius: var(--pmex-faq-radius) !important;
  border: 1px solid var(--pmex-faq-border) !important;
  background: var(--c-FFFFFF) !important;
  box-shadow: none !important;
  margin: 0 !important;
  transition:
    transform 0.3s ease,
    border-color 0.3s ease,
    box-shadow 0.3s ease,
    background-color 0.3s ease !important;
}

/* Index-style sage gradient wash on hover / open (skip if page already has .feature-card-gradient) */
html[data-css~="site-faq-accordion-4"] body :is(.faq-item, .fi, .dm-acc, .mb-acc, [data-faq-item]):not(:has(.feature-card-gradient))::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  background: var(--grad-w);
  opacity: 0;
  transition: var(--transition-fade);
}

html[data-css~="site-faq-accordion-4"] body :is(.faq-item, .fi, .dm-acc, .mb-acc, [data-faq-item]) > * {
  position: relative;
  z-index: 1;
}

@media (hover: hover) and (pointer: fine) {
  html[data-css~="site-faq-accordion-4"] body :is(.faq-item, .fi, .dm-acc, .mb-acc, [data-faq-item]):hover {
    transform: var(--lift-hover) !important;
    border-color: var(--pmex-faq-border-hover) !important;
    box-shadow: var(--pmex-faq-shadow) !important;
  }

  html[data-css~="site-faq-accordion-4"] body :is(.faq-item, .fi, .dm-acc, .mb-acc, [data-faq-item]):not(:has(.feature-card-gradient)):hover::before {
    opacity: 1;
  }
}

html[data-css~="site-faq-accordion-4"] body :is(.faq-item, .fi, .dm-acc, .mb-acc, [data-faq-item]):focus-within {
  border-color: var(--pmex-faq-border-hover) !important;
  box-shadow: var(--pmex-faq-shadow) !important;
}

html[data-css~="site-faq-accordion-4"] body :is(.faq-item, .fi, .dm-acc, .mb-acc, [data-faq-item]):not(:has(.feature-card-gradient)):focus-within::before {
  opacity: 1;
}

/* Open / expanded state keeps the soft elevated look */
html[data-css~="site-faq-accordion-4"] body :is(
  .faq-item.open,
  .faq-item:has([aria-expanded="true"]),
  .fi.open,
  .dm-acc.is-open,
  .mb-acc.is-open,
  [data-faq-item]:has([aria-expanded="true"])
) {
  border-color: var(--pmex-faq-border-hover) !important;
  box-shadow: var(--pmex-faq-shadow) !important;
}

html[data-css~="site-faq-accordion-4"] body :is(
  .faq-item.open,
  .faq-item:has([aria-expanded="true"]),
  .fi.open,
  .dm-acc.is-open,
  .mb-acc.is-open,
  [data-faq-item]:has([aria-expanded="true"])
):not(:has(.feature-card-gradient))::before {
  opacity: 1;
}

/* Stack / grid spacing + alignment (cards were touching after margin reset) */
html[data-css~="site-faq-accordion-4"] body :is(.space-y-2, .space-y-3, .dm-accs, .mb-accs, [data-faq-list]) {
  display: flex !important;
  flex-direction: column !important;
  gap: 12px !important;
