/* ===== layout standards: container, section spacing, heading gap, grid gaps  [data-css~="layout"] ===== */
/* One source for page spacing. Documented in README.md (Layout and spacing standards).
   Breakpoints: mobile < 640px, tablet 640-1023px, laptop/desktop >= 1024px.
   The logo marquee (partials/marquee.html) does not use these classes and keeps its own spacing. */
:root[data-css~="layout"] {
  --pmex-container-max: 1260px;
  --pmex-gutter: 20px;
  --pmex-section-y: 32px;
  --pmex-head-gap: 32px;
  --pmex-card-gap: 16px;
  --pmex-split-gap: 32px;
}
@media (min-width: 640px) {
  :root[data-css~="layout"] { --pmex-gutter: 24px; }
}
@media (min-width: 768px) {
  :root[data-css~="layout"] { --pmex-split-gap: 40px; }
}
@media (min-width: 1024px) {
  :root[data-css~="layout"] { --pmex-gutter: 40px; --pmex-section-y: 40px; --pmex-head-gap: 40px; --pmex-split-gap: 48px; }
}
[data-css~="layout"] .pmex-container {
  width: 100%;
  max-width: var(--pmex-container-max);
  margin-inline: auto;
  padding-inline: var(--pmex-gutter);
}
[data-css~="layout"] .pmex-section { padding-block: var(--pmex-section-y); }
[data-css~="layout"] .pmex-section-head { margin-bottom: var(--pmex-head-gap); }
[data-css~="layout"] .pmex-section-head + * { margin-top: 0; }
[data-css~="layout"] .pmex-card-grid { gap: var(--pmex-card-gap); }
[data-css~="layout"] .pmex-split { gap: var(--pmex-split-gap); }
/* Long-form specialty heroes (approved-longform-specialty block sets 100px padding and a 520px min-height with !important): on layout pages the hero uses the shared section padding like every other section. */
[data-css~="layout"] :is(.specialty-content, [data-approved-longform-page]) [data-specialty-hero].hero-bg-gradient.pmex-section { padding-block: var(--pmex-section-y) !important; min-height: 0; }
/* Specialties hub (specialties/index.html): the green band uses the shared section padding, and each group heading sits the shared heading gap above its cards. */
[data-css~="layout"] .spec-hub-main.spec-hub-main-mid { padding-block: var(--pmex-section-y); padding-inline: var(--pmex-gutter); }
[data-css~="layout"] .spec-hub-section > h2 { margin-bottom: var(--pmex-head-gap); }

/* ===== home page responsive fixes (index.html)  [data-css~="home-responsive"] ===== */
/* Hero, 640-1023px: the photo's white fade covers about 60% of the width, so keep the copy inside it. */
@media (min-width: 640px) and (max-width: 1023px) {
  [data-css~="home-responsive"] .pmex-hero-content { max-width: min(460px, 60vw); }
}
@media (min-width: 768px) and (max-width: 1023px) {
  [data-css~="home-responsive"] [data-pmex-lifecycle] #lifecycle-sidebar { width: 30%; padding: 14px 10px; }
  [data-css~="home-responsive"] [data-pmex-lifecycle] #lifecycle-sidebar button { gap: 10px; padding: 10px; }
  [data-css~="home-responsive"] [data-pmex-lifecycle] #lifecycle-panel { padding: 16px; }
  [data-css~="home-responsive"] [data-pmex-lifecycle] #normal-content { grid-template-columns: minmax(0, 1fr) minmax(180px, 0.75fr); gap: 14px; }
}
/* Hero background from 640px: plain white fade over the photo (no green glow), a little wider so the copy never sits on the image. */
@media (min-width: 640px) {
  [data-css~="home-responsive"] .pmex-hero-index.hero-bg-gradient {
    background-image: linear-gradient(to right, var(--c-FFFFFF) 44%, var(--c-FFFFFF-a78) 56%, transparent 66%), var(--hero-bg-desktop, var(--hero-bg-img, none));
  }
}
/* Hero: grey trust and phone line under the buttons. */
[data-css~="home-responsive"] .pmex-hero-meta { margin: 16px 0 0; font-size: 13px; line-height: 1.6; color: var(--c-676767); }
[data-css~="home-responsive"] .pmex-hero-meta span { margin-inline: 4px; }
[data-css~="home-responsive"] .pmex-hero-meta a { color: var(--c-505050); font-weight: 500; text-decoration: none; white-space: nowrap; }
[data-css~="home-responsive"] .pmex-hero-meta a:hover { text-decoration: underline; text-underline-offset: 3px; }
/* Hero floating cards (1024px+): never closer than 24px to the end of the copy. The copy column starts at the 1260px
   container edge + 40px and is at most 500px (heading) / 480px (paragraph, 1024-1279px) or 530px (paragraph, 1280px+). */
@media (min-width: 1024px) {
  [data-css~="home-responsive"] .pmex-hero-index .pmex-hero-card--expertise { left: max(calc(49.3% - 10px), calc(max(0px, (100% - 1260px) / 2) + 564px)); }
  [data-css~="home-responsive"] .pmex-hero-index .pmex-hero-card--receivables { left: max(calc(38.5% + 96px), calc(max(0px, (100% - 1260px) / 2) + 544px)); }
}
@media (min-width: 1280px) {
  [data-css~="home-responsive"] .pmex-hero-index .pmex-hero-card--receivables { left: max(calc(38.5% + 96px), calc(max(0px, (100% - 1260px) / 2) + 594px)); }
}
/* Billing services (1024px+): both columns share the same top and bottom. The form card grows to the height of the copy
   (form centred inside it) and the "Prefer to call?" line sits on the bottom edge. */
@media (min-width: 1024px) {
  [data-css~="home-responsive"] #pmex-billing-services .pmex-split { align-items: stretch; }
  [data-css~="home-responsive"] #pmex-billing-services [data-billing-card] { display: flex; flex-direction: column; }
  [data-css~="home-responsive"] #pmex-billing-services [data-billing-card] > :first-child { flex: 1 1 auto; display: flex; flex-direction: column; justify-content: center; }
}
/* Claims lifecycle (#pmex-claims-lifecycle): step track + one detail panel (js/claims-flow.js). No scroll effects.
   Track: five numbered dots on a grey line; the line fills green up to the active step (--pmex-flow-progress, 0..1),
   earlier steps get a green ring, the active step a solid green dot. Below 768px only the numbers show; the panel
   carries the title. Panels share one grid cell, so the box keeps the tallest step's height and nothing jumps. */
[data-css~="home-responsive"] .pmex-flow-intro { margin-top: 16px; }
[data-css~="home-responsive"] .pmex-flow-intro p { margin: 0 auto; max-width: 520px; font-size: 14px; line-height: 1.6; color: var(--c-676767); }
[data-css~="home-responsive"] .pmex-flow { --pmex-flow-progress: 0; --pmex-flow-dot: 36px; }
[data-css~="home-responsive"] .pmex-flow-track { position: relative; display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); margin-bottom: 24px; }
[data-css~="home-responsive"] .pmex-flow-track::before,
