/* Claims lifecycle scroll mode (js/claims-flow.js adds .is-scroll on 1024px+ wide screens where the stage fits under the header): the stage
   sticks under the header (top is set by the script) and the empty ::after block below it (a runway, not padding: a sticky box cannot move into its parent padding) is the scroll distance that
   moves through the five steps (--pmex-flow-runway = 4 x 360px). */
[data-css~="home-responsive"] .pmex-flow.is-scroll::after { content: ""; display: block; height: var(--pmex-flow-runway, 1440px); }
[data-css~="home-responsive"] .pmex-flow.is-scroll .pmex-flow-stage { position: sticky; top: 88px; z-index: 2; background: var(--c-FFFFFF); }
[data-css~="home-responsive"] .pmex-flow.is-scroll .pmex-flow-panel { transition: opacity .35s ease, visibility .35s ease; }
/* Claims lifecycle on short desktop screens (laptops, zoomed browsers): a more compact stage so it still fits and sticks */
@media (min-width: 1024px) and (max-height: 820px) {
  [data-css~="home-responsive"] .pmex-flow { --pmex-flow-dot: 34px; }
  [data-css~="home-responsive"] .pmex-flow-track { margin-bottom: 16px; }
  [data-css~="home-responsive"] .pmex-flow-step { gap: 6px; }
  [data-css~="home-responsive"] .pmex-flow-label { font-size: 13px; }
  [data-css~="home-responsive"] .pmex-flow-panel { gap: 32px; padding: 24px 32px; }
  [data-css~="home-responsive"] .pmex-flow-title { margin: 6px 0 8px; }
  [data-css~="home-responsive"] .pmex-flow-desc { margin-bottom: 14px; font-size: 14px; line-height: 1.6; }
  [data-css~="home-responsive"] .pmex-flow-points li { padding: 10px 14px; }
  [data-css~="home-responsive"] .pmex-flow-side { gap: 10px; padding: 16px; }
  [data-css~="home-responsive"] .pmex-flow-side img { width: 44px; height: 44px; }
  [data-css~="home-responsive"] .pmex-flow-metric strong { font-size: 32px; }
}
/* Platform windows on small phones: the systems grid and the window head never push past the window edge */
[data-css~="home-responsive"] .pmex-plat-systems { grid-template-columns: repeat(2, minmax(0, 1fr)); }
[data-css~="home-responsive"] .pmex-plat-systems li { min-width: 0; overflow-wrap: anywhere; }
[data-css~="home-responsive"] .pmex-plat-window-head { flex-wrap: wrap; row-gap: 8px; }
@media (max-width: 479px) {
  [data-css~="home-responsive"] .pmex-plat-panel { padding: 16px; }
  [data-css~="home-responsive"] .pmex-plat-systems { gap: 8px; }
  [data-css~="home-responsive"] .pmex-plat-systems li { gap: 8px; min-height: 44px; padding: 10px; font-size: 13px; }
}
@media (max-width: 359px) {
  [data-css~="home-responsive"] .pmex-plat-systems { grid-template-columns: minmax(0, 1fr); }
}
/* Claims lifecycle: a taller panel on large, tall screens (more breathing room; short screens keep the compact panel so the sticky stage still fits) */
@media (min-width: 1024px) and (min-height: 821px) {
  [data-css~="home-responsive"] .pmex-flow-track { margin-bottom: 40px; }
  [data-css~="home-responsive"] .pmex-flow-panel { min-height: 500px; align-items: stretch; padding: 52px 56px; gap: 56px; }
  [data-css~="home-responsive"] .pmex-flow-title { margin: 10px 0 16px; font-size: 22px; }
  [data-css~="home-responsive"] .pmex-flow-desc { margin-bottom: 28px; }
  [data-css~="home-responsive"] .pmex-flow-side { align-self: stretch; padding: 32px 24px; }
}
@media (min-width: 1024px) and (max-height: 820px) {
  [data-css~="home-responsive"] .pmex-flow-panel { min-height: clamp(300px, calc(100vh - 230px), 450px); align-items: stretch; }
  [data-css~="home-responsive"] .pmex-flow-side { align-self: stretch; }
}

/* Claims lifecycle: the copy column lines up with the metric box. Step label at the box top, point cards at the box bottom. */
@media (min-width: 1024px) {
  [data-css~="home-responsive"] .pmex-flow-panel { align-items: stretch; }
  [data-css~="home-responsive"] .pmex-flow-main { display: flex; flex-direction: column; }
  [data-css~="home-responsive"] .pmex-flow-main > .pmex-flow-points { margin-top: auto; }
}
